INSERT INTO public.incidents (id, organization_id, reference, title, description, status, reported_severity, ai_suggested_severity, approved_severity, category, system_id, environment, detected_at, acknowledged_at, resolved_at, resolution_summary, knowledge_promoted, created_at) VALUES
  ('b1000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','INC-2041','Kart switch tarafinda zaman asimi orani %12 seviyesine cikti','Saat 09:40 itibariyla POS islemlerinde ISO 8583 yanit suresi 2500 ms uzerine cikti. Kart switch uzerinde baglanti havuzu doldu ve zaman asimi orani %12 seviyesine ulasti. Etkilenen islem tipi: satis ve iptal.','resolved','P1','P1','P1','performance','a1000000-0000-0000-0000-000000000001','prod', now() - interval '26 days', now() - interval '26 days' + interval '6 minutes', now() - interval '26 days' + interval '95 minutes','Baglanti havuzu limiti 120 den 300 e cikarildi, sizinti yapan idle baglantilar icin timeout eklendi. Islem basarim orani normale dondu.',true, now() - interval '26 days'),
  ('b1000000-0000-0000-0000-000000000002','11111111-1111-1111-1111-111111111111','INC-2088','Odeme gecidinde 3D Secure dogrulama hatalari artti','Odeme gecidi uzerinden yapilan 3D Secure dogrulamalarinda saglayici sertifikasinin yenilenmesi sonrasi %8 oraninda hata alinmaya baslandi. Hata kodu: SSL_HANDSHAKE_FAILURE.','resolved','P2','P2','P2','integration','a1000000-0000-0000-0000-000000000002','prod', now() - interval '18 days', now() - interval '18 days' + interval '11 minutes', now() - interval '18 days' + interval '140 minutes','Ara sertifika zinciri truststore a eklendi ve servis kademeli olarak yeniden baslatildi.',true, now() - interval '18 days'),
  ('b1000000-0000-0000-0000-000000000003','11111111-1111-1111-1111-111111111111','INC-2130','Gun sonu mutabakat dosyasi eksik satirla uretildi','Mutabakat servisi gun sonu dosyasini uretti ancak son 40 dakikalik islemler dosyada yer almadi. Kaynak kuyruk tuketimi gecikmeli calisti.','closed','P2','P2','P2','data_integrity','a1000000-0000-0000-0000-000000000005','prod', now() - interval '12 days', now() - interval '12 days' + interval '25 minutes', now() - interval '12 days' + interval '180 minutes','Kuyruk tuketici sayisi artirildi, eksik satirlar icin duzeltme dosyasi uretildi ve karsi tarafa iletildi.',true, now() - interval '12 days'),
  ('b1000000-0000-0000-0000-000000000004','11111111-1111-1111-1111-111111111111','INC-2166','Mobil uygulamada giris sonrasi bakiye ekrani bos geliyor','Mobil bankacilik uygulamasinda bazi musteriler giris yaptiktan sonra bakiye ekraninin bos geldigini bildirdi. Backend tarafinda cache invalidation hatasi supheleniyor.','investigating','P3',NULL,'P3','availability','a1000000-0000-0000-0000-000000000004','prod', now() - interval '3 days', now() - interval '3 days' + interval '15 minutes', NULL, NULL,false, now() - interval '3 days'),
  ('b1000000-0000-0000-0000-000000000005','11111111-1111-1111-1111-111111111111','INC-2171','Kart switch zaman asimi uyarilari yeniden yukseldi','Sabah yogunlugunda kart switch tarafinda yanit suresi tekrar 1800 ms uzerine cikti ve zaman asimi uyarilari alinmaya baslandi. Etki su an sinirli.','triage_pending','P2',NULL,NULL,NULL,'a1000000-0000-0000-0000-000000000001','prod', now() - interval '20 hours', NULL, NULL, NULL,false, now() - interval '20 hours'),
  ('b1000000-0000-0000-0000-000000000006','11111111-1111-1111-1111-111111111111','INC-2174','Cekirdek bankacilikta gece batch islemi gec tamamlandi','Gece batch islemi normalde 03:20 de biterken bu gece 05:10 da tamamlandi. Sabah acilis raporlari gecikmeli uretildi.','new','P3',NULL,NULL,NULL,'a1000000-0000-0000-0000-000000000003','prod', now() - interval '9 hours', NULL, NULL, NULL,false, now() - interval '9 hours'),
  ('b1000000-0000-0000-0000-000000000007','22222222-2222-2222-2222-222222222222','INC-5001','Sanal POS taksitli islemlerde hata','PSP tarafinda taksitli islemlerde bankaya gonderilen alan formati hatali.','investigating','P2',NULL,'P2','integration','a1000000-0000-0000-0000-000000000006','prod', now() - interval '2 days', now() - interval '2 days', NULL, NULL,false, now() - interval '2 days');
