INSERT INTO public.root_cause_hypotheses (organization_id, incident_id, hypothesis, rationale, confidence, status, created_at) VALUES
  ('11111111-1111-1111-1111-111111111111','b1000000-0000-0000-0000-000000000001','Kart switch baglanti havuzu limiti yogunlukta yetersiz kaliyor','Yanit suresi artisi ile eszamanli olarak aktif baglanti sayisi limite dayandi. Benzer iki gecmis kayitta ayni desen var.',0.78,'confirmed', now() - interval '26 days' + interval '20 minutes'),
  ('11111111-1111-1111-1111-111111111111','b1000000-0000-0000-0000-000000000002','Saglayici ara sertifikasi truststore da eksik','Hata kodu SSL_HANDSHAKE_FAILURE ve sertifika yenileme zamani ortusuyor.',0.81,'confirmed', now() - interval '18 days' + interval '30 minutes');
INSERT INTO public.recommended_actions (id, organization_id, incident_id, title, detail, risk_level, confidence, decision, decision_note, created_at) VALUES
  ('c1000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','b1000000-0000-0000-0000-000000000001','Baglanti havuzu limitini kademeli artir','Havuz limitini 120 den 300 e cikarin ve idle baglantilar icin 60 saniye timeout tanimlayin.','medium',0.74,'approved','Degisiklik yonetimi onayi ile uygulandi.', now() - interval '26 days' + interval '25 minutes'),
  ('c1000000-0000-0000-0000-000000000002','11111111-1111-1111-1111-111111111111','b1000000-0000-0000-0000-000000000001','Switch onunde devre kesici esigini dusur','Ard arda 5 zaman asiminda devre kesiciyi ac ve 30 saniye sonra yarim ac konuma gec.','low',0.58,'rejected','Bu incident icin gerekli gorulmedi.', now() - interval '26 days' + interval '26 minutes'),
  ('c1000000-0000-0000-0000-000000000003','11111111-1111-1111-1111-111111111111','b1000000-0000-0000-0000-000000000002','Ara sertifika zincirini truststore a ekle','Saglayicinin yeni ara sertifikasini truststore a ekleyip servisleri kademeli yeniden baslatin.','medium',0.8,'approved','Uygulandi.', now() - interval '18 days' + interval '40 minutes');
