INSERT INTO public.postmortems (organization_id, incident_id, timeline, root_cause, impact, lessons, preventive_actions, status, approved_at, created_at) VALUES
  ('11111111-1111-1111-1111-111111111111','b1000000-0000-0000-0000-000000000001','09:40 ilk uyari, 09:46 triage, 10:05 kok neden, 11:15 cozum.','Kart switch baglanti havuzu limiti yogun saat trafigi icin yetersizdi.','Yaklasik 95 dakika boyunca POS islemlerinin %12 si zaman asimina ugradi.','Kapasite testleri gercek yogun saat profiliyle yapilmali.','Havuz limiti kalici artirildi, kapasite alarmi eklendi.','approved', now() - interval '25 days', now() - interval '25 days'),
  ('11111111-1111-1111-1111-111111111111','b1000000-0000-0000-0000-000000000002','Sertifika yenileme sonrasi hata artisi, truststore guncellemesi ile cozum.','Ara sertifika zinciri eksikligi.','3D Secure dogrulamalarinin %8 i basarisiz oldu.','Sertifika yenilemeleri degisiklik takvimine alinmali.','Sertifika son kullanma izleme alarmi kuruldu.','approved', now() - interval '17 days', now() - interval '17 days');
